from pathlib import Path

from app.services import users

DATA_DIR = Path(__file__).resolve().parent.parent.parent / "data"


def _parse_path(raw: object) -> list[str] | None:
    """Validate a data-relative path, returning its segments or None when invalid."""
    if not isinstance(raw, str):
        return None
    if raw == "":
        return []
    segments = raw.split("/")
    if any(segment in ("", ".", "..") for segment in segments):
        return None
    return segments


def handle_list_files(params: dict) -> tuple[int, dict]:
    segments = _parse_path(params.get("dir", ""))
    if segments is None:
        return 400, {"error": "invalid path"}
    root = DATA_DIR.resolve()
    directory = root.joinpath(*segments).resolve()
    if not directory.is_relative_to(root) or not directory.is_dir():
        return 404, {"error": "not found"}
    files = sorted(entry.name for entry in directory.iterdir() if entry.is_file())
    return 200, {"files": files}


